import java.util.*;

class FindSumPairs {
  private final int[] nums1, nums2;
  private final Map<Integer, Integer> counts = new HashMap<>();

  public FindSumPairs(int[] nums1, int[] nums2) {
    this.nums1 = nums1;
    this.nums2 = nums2;
    for (int x : nums2) counts.merge(x, 1, Integer::sum);
  }

  public void add(int index, int val) {
    int old = nums2[index];
    counts.put(old, counts.get(old) - 1);
    counts.merge(old + val, 1, Integer::sum);
    nums2[index] = old + val;
  }

  public int count(int tot) {
    int ans = 0;
    for (int x : nums1) ans += counts.getOrDefault(tot - x, 0);
    return ans;
  }
}
